{
  "messages": [
    {
      "time": "13:15",
      "author": "Veikko Vikkelä",
      "role": "Field Engineer",
      "text": "Hi Erkki! trn 87 had its SFP changed, link up, optics normal, counters zero. But traffic is still not flowing."
    },
    {
      "time": "13:17",
      "author": "Erkki Expert",
      "role": "Network Expert",
      "text": "Moi Veikko. Let me check the port status from my side. Yes, physical link is up but protocol is down."
    },
    {
      "time": "13:19",
      "author": "Veikko Vikkelä",
      "role": "Field Engineer",
      "text": "Should I try to reboot the whole box or maybe swap the SFP again?"
    },
    {
      "time": "13:21",
      "author": "Erkki Expert",
      "role": "Network Expert",
      "text": "No, disable the interface, wait a bit, enable it again; don't reboot it and don't swap the SFP again."
    },
    {
      "time": "13:23",
      "author": "Veikko Vikkelä",
      "role": "Field Engineer",
      "text": "Okay, I will toggle the port admin status now. Waiting a few seconds..."
    },
    {
      "time": "13:25",
      "author": "Veikko Vikkelä",
      "role": "Field Engineer",
      "text": "Done on TRN087, traffic is back. Looks like it did the trick! :)"
    },
    {
      "time": "13:27",
      "author": "Erkki Expert",
      "role": "Network Expert",
      "text": "Great, I see the interface is fully up and traffic is running fine. We are good to go."
    }
  ]
}
